{
  "name": "rrpg-server",
  "version": "1.0.0",
  "description": "Rorphic RPG Real-Time WebSocket Backend Server",
  "main": "server.js",
  "scripts": {
    "start": "node server.js"
  },
  "dependencies": {
    "express": "^4.19.2",
    "ws": "^8.16.0",
    "cors": "^2.8.5"
  }
}

const express = require('express');
const http = require('http');
const WebSocket = require('ws');
const cors = require('cors');

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

let roomState = {
  sessionName: "Campaign of the Blood Moon",
  master: "Game Master",
  participants: [
    { id: "1", name: "Game Master", role: "GM", status: "online" },
    { id: "2", name: "Valeros (Fighter)", role: "Player", status: "online" },
    { id: "3", name: "Merisiel (Rogue)", role: "Player", status: "online" },
    { id: "4", name: "Kyra (Cleric)", role: "Player", status: "online" }
  ],
  tokens: [
    { id: "t1", name: "Valeros", x: 4, y: 5, color: "#D4AF37", hp: 32, maxHp: 32 },
    { id: "t2", name: "Goblin Scout", x: 8, y: 3, color: "#8B0000", hp: 12, maxHp: 12 }
  ],
  chatLogs: [
    { id: "c1", sender: "System", text: "Welcome to Rorphic RPG Session #1.", time: "20:00" },
    { id: "c2", sender: "Valeros", text: "I draw my longsword and check the shadows.", time: "20:01" },
    { id: "c3", sender: "Game Master", text: "Roll Initiative!", time: "20:02" }
  ]
};

wss.on('connection', (ws) => {
  console.log('New client connected.');

  // Send initial state
  ws.send(JSON.stringify({ type: 'INIT_STATE', payload: roomState }));

  ws.on('message', (message) => {
    try {
      const data = JSON.parse(message);
      console.log('Received:', data.type);

      if (data.type === 'ACTION_ROLL_DICE') {
        const rollResult = {
          id: 'c_' + Date.now(),
          sender: data.payload.sender || 'Player',
          text: `Rolled ${data.payload.expression}: Result = ${data.payload.total} [${data.payload.rolls.join(', ')}]`,
          time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
        };
        roomState.chatLogs.push(rollResult);
        broadcast({ type: 'STATE_UPDATE', payload: roomState });
      } else if (data.type === 'ACTION_MOVE_TOKEN') {
        const token = roomState.tokens.find(t => t.id === data.payload.tokenId);
        if (token) {
          token.x = data.payload.x;
          token.y = data.payload.y;
          broadcast({ type: 'STATE_UPDATE', payload: roomState });
        }
      } else if (data.type === 'ACTION_CHAT') {
        const chatMsg = {
          id: 'c_' + Date.now(),
          sender: data.payload.sender,
          text: data.payload.text,
          time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
        };
        roomState.chatLogs.push(chatMsg);
        broadcast({ type: 'STATE_UPDATE', payload: roomState });
      }
    } catch (e) {
      console.error('Invalid message format:', e);
    }
  });

  ws.on('close', () => {
    console.log('Client disconnected.');
  });
});

function broadcast(data) {
  const message = JSON.stringify(data);
  wss.clients.forEach(client => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(message);
    }
  });
}

app.get('/api/status', (req, res) => {
  res.json({ status: 'active', server: 'RRPG WebSocket & API Backend', rooms: 1 });
});

const PORT = process.env.PORT || 4000;
server.listen(PORT, () => {
  console.log(`RRPG Backend Server running on port ${PORT}`);
});

{
  "name": "rrpg-server",
  "version": "1.0.0",
  "description": "Rorphic RPG WebSocket and REST Backend",
  "main": "server.js",
  "scripts": {
    "start": "node server.js"
  },
  "dependencies": {
    "cors": "^2.8.5",
    "express": "^4.19.2",
    "ws": "^8.16.0"
  }
}

const express = require('express');
const http = require('http');
const WebSocket = require('ws');
const cors = require('cors');
const path = require('path');

const app = express();
app.use(cors());
app.use(express.json());

// Serve static frontend if built
app.use(express.static(path.join(__dirname, '../web/dist')));

const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

// Initial Game Room State
let roomState = {
  roomId: 'rpg-main-room',
  campaignName: 'Chronicles of the Iron Crown',
  gm: 'Game Master',
  participants: [
    { id: 'p1', name: 'Valen Shadowstep', role: 'Player', hp: 32, maxHp: 35, ac: 16, status: 'Active' },
    { id: 'p2', name: 'Lyra Dawnwhisper', role: 'Player', hp: 24, maxHp: 28, ac: 14, status: 'Active' },
    { id: 'p3', name: 'Grimm Stonehammer', role: 'Player', hp: 45, maxHp: 45, ac: 18, status: 'Active' },
    { id: 'p4', name: 'Malakor the Defiler', role: 'GM', hp: 80, maxHp: 80, ac: 17, status: 'GM' }
  ],
  tokens: [
    { id: 't1', name: 'Valen', x: 4, y: 4, color: '#D4AF37', type: 'player' },
    { id: 't2', name: 'Lyra', x: 5, y: 4, color: '#3B82F6', type: 'player' },
    { id: 't3', name: 'Grimm', x: 4, y: 5, color: '#10B981', type: 'player' },
    { id: 't4', name: 'Goblin Warchief', x: 10, y: 10, color: '#EF4444', type: 'enemy' },
    { id: 't5', name: 'Goblin Scout', x: 9, y: 10, color: '#EF4444', type: 'enemy' }
  ],
  messages: [
    { id: 'm1', sender: 'System', text: 'Welcome to Rorphic RPG Session. Room initialized.', timestamp: new Date().toLocaleTimeString() },
    { id: 'm2', sender: 'Malakor', text: 'The cavern echoes with the sound of grinding stone and distant marching.', timestamp: new Date().toLocaleTimeString() }
  ],
  gridSize: 20
};

// Broadcast to all connected clients
function broadcastState() {
  const data = JSON.stringify({ type: 'ROOM_STATE', payload: roomState });
  wss.clients.forEach(client => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(data);
    }
  });
}

wss.on('connection', (ws) => {
  console.log('New client connected.');

  // Send initial state
  ws.send(JSON.stringify({ type: 'ROOM_STATE', payload: roomState }));

  ws.on('message', (message) => {
    try {
      const data = JSON.parse(message);

      if (data.type === 'UPDATE_TOKENS') {
        roomState.tokens = data.payload;
        broadcastState();
      } else if (data.type === 'SEND_MESSAGE') {
        const newMsg = {
          id: 'm_' + Date.now(),
          sender: data.payload.sender || 'Anonymous',
          text: data.payload.text,
          timestamp: new Date().toLocaleTimeString()
        };
        roomState.messages.push(newMsg);
        broadcastState();
      } else if (data.type === 'ROLL_DICE') {
        const rollResult = data.payload; // { roller, dice, total, breakdown }
        const newMsg = {
          id: 'm_' + Date.now(),
          sender: 'Dice Bot',
          text: `${rollResult.roller} rolled ${rollResult.dice} -> Total: **${rollResult.total}** (${rollResult.breakdown})`,
          timestamp: new Date().toLocaleTimeString()
        };
        roomState.messages.push(newMsg);
        broadcastState();
      }
    } catch (err) {
      console.error('Failed to parse incoming WebSocket message:', err);
    }
  });

  ws.on('close', () => {
    console.log('Client disconnected.');
  });
});

// REST fallback API
app.get('/api/room', (req, res) => {
  res.json(roomState);
});

const PORT = process.env.PORT || 3001;
server.listen(PORT, () => {
  console.log(`Rorphic RPG Backend Server running on port ${PORT}`);
});

{
  "name": "rrpg-server",
  "version": "1.0.0",
  "description": "Rorphic RPG WebSocket & Express Backend Server",
  "main": "server.js",
  "scripts": {
    "start": "node server.js"
  },
  "dependencies": {
    "cors": "^2.8.5",
    "express": "^4.19.2",
    "ws": "^8.16.0"
  }
}

const express = require('express');
const http = require('http');
const { WebSocketServer } = require('ws');
const cors = require('cors');

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);
const wss = new WebSocketServer({ server });

// State for the active tabletop session
const sessionState = {
  tokens: [
    { id: '1', name: 'Valeros (Fighter)', x: 4, y: 4, hp: 32, maxHp: 32, color: '#D4AF37' },
    { id: '2', name: 'Merisiel (Rogue)', x: 6, y: 4, hp: 24, maxHp: 24, color: '#58111A' },
    { id: '3', name: 'Goblin Scout', x: 2, y: 2, hp: 10, maxHp: 10, color: '#8B0000' }
  ],
  messages: [
    { id: 'm1', user: 'System', text: 'Welcome to Rorphic RPG Session #409.', time: '20:00' },
    { id: 'm2', user: 'Valeros', text: 'Drawing my longsword. Let\'s clear this room.', time: '20:01' }
  ],
  diceRolls: [
    { id: 'd1', user: 'Valeros', expression: '1d20+5', result: 18, total: 23, time: '20:02' }
  ]
};

// Broadcast to all connected clients
function broadcast(data) {
  const message = JSON.stringify(data);
  wss.clients.forEach(client => {
    if (client.readyState === 1) { // OPEN
      client.send(message);
    }
  });
}

wss.on('connection', (ws) => {
  console.log('New client connected to RRPG WebSocket server.');

  // Send current state to newly connected client
  ws.send(JSON.stringify({
    type: 'INIT_STATE',
    payload: sessionState
  }));

  ws.on('message', (rawMessage) => {
    try {
      const message = JSON.parse(rawMessage);
      console.log('Received action:', message.type);

      switch (message.type) {
        case 'MOVE_TOKEN': {
          const { id, x, y } = message.payload;
          const token = sessionState.tokens.find(t => t.id === id);
          if (token) {
            token.x = x;
            token.y = y;
            broadcast({ type: 'STATE_UPDATE', payload: sessionState });
          }
          break;
        }
        case 'ROLL_DICE': {
          const { user, expression, result, total } = message.payload;
          const rollEntry = {
            id: 'd_' + Date.now(),
            user,
            expression,
            result,
            total,
            time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
          };
          sessionState.diceRolls.unshift(rollEntry);
          if (sessionState.diceRolls.length > 50) sessionState.diceRolls.pop();

          // Also add to chat log
          const chatEntry = {
            id: 'm_' + Date.now(),
            user: 'DiceBot',
            text: `${user} rolled ${expression} ➔ Result: [${result}] Total: ${total}`,
            time: rollEntry.time
          };
          sessionState.messages.unshift(chatEntry);

          broadcast({ type: 'STATE_UPDATE', payload: sessionState });
          break;
        }
        case 'SEND_CHAT': {
          const { user, text } = message.payload;
          const chatEntry = {
            id: 'm_' + Date.now(),
            user,
            text,
            time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
          };
          sessionState.messages.unshift(chatEntry);
          if (sessionState.messages.length > 100) sessionState.messages.pop();

          broadcast({ type: 'STATE_UPDATE', payload: sessionState });
          break;
        }
        default:
          console.warn('Unknown message type:', message.type);
      }
    } catch (err) {
      console.error('Failed to parse WebSocket message:', err);
    }
  });

  ws.on('close', () => {
    console.log('Client disconnected.');
  });
});

app.get('/api/health', (req, res) => {
  res.json({ status: 'ok', service: 'rrpg-server', timestamp: new Date().toISOString() });
});

const PORT = process.env.PORT || 4000;
server.listen(PORT, () => {
  console.log(`Rorphic RPG backend server running on http://localhost:${PORT}`);
});
